async function api(url,opt={}){const r=await fetch(url,opt);if(!r.ok){let m=`${r.status} ${r.statusText}`;try{const j=await r.json(),d=j.detail;if(d&&typeof d==='object'&&d.code)m=t(d.code)+(d.detail?`: ${d.detail}`:'');else if(typeof d==='string')m=d}catch{}throw new Error(m)}const ct=r.headers.get('content-type')||'';return ct.includes('json')?r.json():r}
function esc(s=''){return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function t(k,v={}){let s=L[k]||LF[k];if(s==null){console.warn('Missing locale key',k);s='—'};for(const [a,b] of Object.entries(v))s=s.replaceAll(`{${a}}`,String(b));return s}
function fmtBytes(n){n=Number(n||0);for(const u of ['B','KB','MB','GB','TB']){if(n<1024||u==='TB')return `${n<10&&u!=='B'?n.toFixed(1):Math.round(n)} ${u}`;n/=1024}}
function fmtTime(sec=0){sec=Math.max(0,Math.round(sec));const h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;return h?`${h}h ${m}m`:m?`${m}m ${s}s`:`${s}s`}
function setTooltip(el,text,rich=false){if(!el)return;el.removeAttribute('title');if(text){el.dataset.tooltip=String(text);if(rich)el.dataset.tooltipRich='1';else delete el.dataset.tooltipRich}else{delete el.dataset.tooltip;delete el.dataset.tooltipRich}}
let tooltipTimer=null,tooltipAnchor=null;
function hideUiTooltip(){clearTimeout(tooltipTimer);tooltipTimer=null;tooltipAnchor=null;const tip=$('#uiTooltip');if(tip)tip.classList.add('hidden')}
function showUiTooltip(el){const text=el?.dataset?.tooltip;if(!text)return;const tip=$('#uiTooltip');if(!tip)return;tooltipAnchor=el;tip.textContent=text;tip.classList.toggle('rich',el.dataset.tooltipRich==='1');tip.classList.remove('hidden');requestAnimationFrame(()=>{if(tooltipAnchor!==el)return;const r=el.getBoundingClientRect(),tr=tip.getBoundingClientRect(),gap=8;let left=Math.min(innerWidth-tr.width-8,Math.max(8,r.left+(r.width-tr.width)/2)),top=r.bottom+gap;if(top+tr.height>innerHeight-8)top=Math.max(8,r.top-tr.height-gap);tip.style.left=left+'px';tip.style.top=top+'px'})}
function scheduleUiTooltip(el){clearTimeout(tooltipTimer);tooltipTimer=setTimeout(()=>showUiTooltip(el),420)}
function installTooltipSystem(){
 const promote=el=>{if(!(el instanceof Element))return;if(el.hasAttribute('title')){const v=el.getAttribute('title');el.removeAttribute('title');if(v&&!el.dataset.tooltip)el.dataset.tooltip=v}for(const n of el.querySelectorAll?.('[title]')||[]){const v=n.getAttribute('title');n.removeAttribute('title');if(v&&!n.dataset.tooltip)n.dataset.tooltip=v}};
 promote(document.documentElement);
 new MutationObserver(ms=>{for(const m of ms){if(m.type==='childList'){for(const n of m.addedNodes)if(n.nodeType===1)promote(n)}else if(m.type==='attributes'){promote(m.target)}}}).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['title']});
 document.addEventListener('pointerover',e=>{const el=e.target.closest?.('[data-tooltip]');if(el)scheduleUiTooltip(el)});
 document.addEventListener('pointerout',e=>{const el=e.target.closest?.('[data-tooltip]');if(el&&!el.contains(e.relatedTarget))hideUiTooltip()});
 document.addEventListener('focusin',e=>{const el=e.target.closest?.('[data-tooltip]');if(el)scheduleUiTooltip(el)});
 document.addEventListener('focusout',e=>{if(e.target.closest?.('[data-tooltip]'))hideUiTooltip()});
 addEventListener('scroll',hideUiTooltip,{passive:true});addEventListener('resize',hideUiTooltip);
}
function currentLang(){const v=localStorage.getItem('eidolarch.language')||'auto';return v==='auto'?((navigator.language||'en').toLowerCase().startsWith('ru')?'ru':'en'):v}
async function loadLocale(){lang=currentLang();try{LF=await api('/api/locales/en.json');L=lang==='en'?LF:await api(`/api/locales/${lang}.json`)}catch(e){console.warn('Locale load failed',e);L=LF||{}}document.documentElement.lang=lang;$$('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));buildSortOptions();applyToolLabels();updateSearchHint()}
function applyToolLabels(){
 $('#modeFolders').textContent=t('nav.folders');$('#modeTags').textContent=t('nav.tags');$('#modeFavorites').textContent=t('nav.favorites');$('#modeDuplicates').textContent=t('nav.duplicates');setTooltip($('#modeFolders'),t('hint.folders'));setTooltip($('#modeTags'),t('hint.tags'));setTooltip($('#modeFavorites'),t('hint.favorites'));setTooltip($('#modeDuplicates'),t('hint.duplicatesMode'));$('#searchSubmit').textContent=t('search.find');setTooltip($('#clearSearch'),t('search.clear'));$('#resetAll').textContent='× '+t('search.reset');setTooltip($('#resetAll'),t('hint.reset'));
 setTooltip($('#backBtn'),t('hint.back'));setTooltip($('#forwardBtn'),t('hint.forward'));setTooltip($('#newWindow'),t('toolbar.newWindow'));setTooltip($('#settingsBtn'),t('toolbar.settings'));setTooltip($('#networkBtn'),t('toolbar.network'));setTooltip($('#jobsBtn'),t('toolbar.jobs'));setTooltip($('#graphBtn'),t('toolbar.graph'));setTooltip($('#helpBtn'),t('toolbar.help'));setTooltip($('#newFolderBtn'),t('hint.newFolder'));setTooltip($('#toggleNavPanel'),t('hint.tagPanel'));setTooltip($('#modelState'),t('hint.modelState'));setTooltip($('#progressWrap'),t('hint.progress'));$('#loadHint').textContent=t('gallery.loading');
 const views={grid:'hint.grid',content:'hint.content',details:'hint.details'};for(const b of $$('.view-switch button'))setTooltip(b,t(views[b.dataset.view]));
 const labels={copy:'bulk.copy',move:'bulk.move',tag:'bulk.tag',delete:'bulk.delete',cancel:'bulk.cancel',undo:'bulk.undo'};for(const b of $$('#bulkbar button'))b.textContent=t(labels[b.dataset.op]);
}
function buildSortOptions(){const map=[['taken_desc','sort.takenDesc'],['taken_asc','sort.takenAsc'],['name_asc','sort.nameAsc'],['name_desc','sort.nameDesc'],['size_desc','sort.sizeDesc'],['size_asc','sort.sizeAsc'],['rating_desc','sort.rating'],['added_desc','sort.added']];$('#sortSelect').innerHTML=map.map(([v,k])=>`<option value="${v}">${esc(t(k))}</option>`).join('');$('#sortSelect').value=localStorage.getItem('eidolarch.sort')||'taken_desc'}

function effectiveTheme(){const v=localStorage.getItem('eidolarch.theme')||'system';return v==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):v}
function applyUiSettings(){const pref=localStorage.getItem('eidolarch.theme')||'system',theme=effectiveTheme();document.documentElement.dataset.theme=theme;document.documentElement.classList.toggle('color-diff',localStorage.getItem('eidolarch.colorDiff')!=='0');document.documentElement.classList.toggle('motion',localStorage.getItem('eidolarch.gridMotion')!=='0');$('#uiTheme').value=pref;$('#uiLanguage').value=localStorage.getItem('eidolarch.language')||'auto';$('#colorDiff').checked=localStorage.getItem('eidolarch.colorDiff')!=='0';$('#gridMotion').checked=localStorage.getItem('eidolarch.gridMotion')!=='0';document.querySelector('meta[name=theme-color]').content=theme==='light'?'#f5f6f8':'#101218'}
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if((localStorage.getItem('eidolarch.theme')||'system')==='system')applyUiSettings()});
addEventListener('storage',async e=>{if(e.key==='eidolarch.language'){await loadLocale();await renderNav();updateCount()}else if(e.key==='eidolarch.theme'){applyUiSettings()}else if(e.key==='eidolarch.graphTag'&&e.newValue){try{const x=JSON.parse(e.newValue);specialMode='';browseMode='tags';selectedTags=[{id:Number(x.id),name:String(x.name)}];await renderNav();await loadGallery(true)}catch{}}});

function filterQuery(){const p=[];if(folderId)p.push('folder_id='+folderId);if(currentRel)p.push('rel='+encodeURIComponent(currentRel));if(selectedTags.length)p.push('tags='+selectedTags.map(x=>x.id).join(','));return p.length?'&'+p.join('&'):''}
function currentScopeName(){if(!folderId)return'';const tail=currentRel?currentRel.split(/[\\/]/).filter(Boolean).pop():'';return tail||folderName.split(/[\\/]/).filter(Boolean).pop()||folderName}
function updateSearchHint(){const name=currentScopeName(),tags=selectedTags.map(x=>'#'+x.name).join(' + ');let hint;if(name&&tags)hint=t('hint.searchScopeFolderTags',{name,tags});else if(name)hint=t('hint.searchScopeFolder',{name});else if(tags)hint=t('hint.searchScopeTags',{tags});else hint=t('hint.searchScopeAll');$('#search').placeholder=hint+'…';setTooltip($('.searchbox'),t('hint.searchLanguage'),true)}
async function loadEntityOptions(){try{const d=await api('/api/entities');entityOptions=d.items||[]}catch{entityOptions=[]}}
function entitySuggestBox(){let box=$('#entitySuggest');if(!box){box=document.createElement('div');box.id='entitySuggest';box.className='entity-suggest hidden';$('.searchbox').appendChild(box)}return box}
function currentAtToken(){const input=$('#search'),pos=input.selectionStart??input.value.length,left=input.value.slice(0,pos),m=left.match(/(?:^|\s)@([^\s@#]*)$/);return m?{prefix:m[1],start:pos-m[1].length-1,end:pos}:null}
function hideEntitySuggest(){entitySuggestIndex=-1;entitySuggestBox().classList.add('hidden')}
function renderEntitySuggest(){const token=currentAtToken(),box=entitySuggestBox();if(!token){hideEntitySuggest();return}const q=token.prefix.toLocaleLowerCase(),items=entityOptions.filter(x=>!q||String(x.name).toLocaleLowerCase().startsWith(q)).slice(0,8);if(!items.length){hideEntitySuggest();return}box.innerHTML=items.map((x,i)=>`<button type="button" data-entity-index="${i}" data-entity-name="${esc(x.name)}"><b>@${esc(x.name)}</b><span>${esc(t('entity.kind.'+(x.kind||'unknown')))} · ${x.photo_count||0}</span></button>`).join('');box.classList.remove('hidden');entitySuggestIndex=-1;box.querySelectorAll('button').forEach(b=>b.onmousedown=e=>{e.preventDefault();insertEntitySuggestion(b.dataset.entityName)})}
function insertEntitySuggestion(name){const input=$('#search'),tok=currentAtToken();if(!tok)return;const before=input.value.slice(0,tok.start),after=input.value.slice(tok.end);input.value=before+'@'+name+' '+after.replace(/^\s*/,'');const pos=(before+'@'+name+' ').length;input.setSelectionRange(pos,pos);hideEntitySuggest();input.focus();$('#clearSearch').classList.remove('hidden')}
function moveEntitySuggest(delta){const buttons=[...entitySuggestBox().querySelectorAll('button')];if(!buttons.length)return false;entitySuggestIndex=(entitySuggestIndex+delta+buttons.length)%buttons.length;buttons.forEach((b,i)=>b.classList.toggle('active',i===entitySuggestIndex));return true}
function acceptEntitySuggest(){const buttons=[...entitySuggestBox().querySelectorAll('button')];if(!buttons.length)return false;const b=buttons[entitySuggestIndex>=0?entitySuggestIndex:0];insertEntitySuggestion(b.dataset.entityName);return true}
function stateObject(){return{searchMode,q:$('#search').value,browseMode,specialMode,folderId,folderName,currentRel,selectedTags:[...selectedTags],sort:$('#sortSelect').value,view:document.body.dataset.view||'grid',scrollY:scrollY}}
function pushHistory(){if(restoringHistory)return;const s=stateObject();historyStack=historyStack.slice(0,historyPos+1);historyStack.push(s);historyPos=historyStack.length-1;updateHistoryButtons()}
async function restoreState(s){if(!s)return;restoringHistory=true;searchMode=s.searchMode;$('#search').value=s.q||'';browseMode=s.browseMode||'folders';specialMode=s.specialMode||'';folderId=s.folderId;folderName=s.folderName||'';currentRel=s.currentRel||'';selectedTags=s.selectedTags||[];$('#sortSelect').value=s.sort||'taken_desc';setView(s.view||'grid',false);await renderNav();if(searchMode&&s.q)await runSearch(false);else await loadGallery(true,false);requestAnimationFrame(()=>scrollTo(0,s.scrollY||0));restoringHistory=false;updateHistoryButtons()}
function updateHistoryButtons(){$('#backBtn').disabled=historyPos<=0;$('#forwardBtn').disabled=historyPos>=historyStack.length-1}

function resultTitle(){if(specialMode==='favorites')return t('nav.favorites');if(specialMode==='duplicates')return t('duplicates.groupsTitle');if(searchMode)return `${t('search.find')}: ${$('#search').value}`;if(selectedTags.length)return `${t('nav.tags')}: ${selectedTags.map(x=>'#'+x.name).join(' + ')}`;if(folderId){const tail=currentRel?currentRel.split(/[\\/]/).filter(Boolean).pop():'';return tail||folderName||t('nav.folders')}return t('gallery.title')}
function updateCount(){$('#resultTitle').textContent=resultTitle();$('#count').textContent=searchMode?String(currentItems.length):`${Math.min(offset,total)} / ${total}`;$('#clearSearch').classList.toggle('hidden',!$('#search').value&&!searchMode);$('#resetAll').classList.toggle('hidden',!folderId&&!selectedTags.length&&!searchMode&&!specialMode);updateSearchHint();updateSelectionBar()}
function updateSelectionBar(){const n=selected.size;$('#selectionCount').classList.toggle('hidden',!n);$('#selectionCount').textContent=n?t('gallery.selected',{n}):'';$('#bulkbar').classList.toggle('hidden',!n);for(const tile of $$('.tile[data-id]'))tile.classList.toggle('selected',selected.has(Number(tile.dataset.id)))}

function tileActions(p){return `<div class="tile-actions ${p.duplicate_count?'with-dupebadge':''}">${p.duplicate_count?`<button class="duplicate-hover-action" data-action="duplicates" data-tooltip="${esc(t('tile.duplicates'))}">⧉</button>`:''}<button data-action="similar" data-tooltip="${esc(t('tile.similar'))}">≈</button><button data-action="favorite" data-tooltip="${esc(t('tile.favorite'))}" class="${p.favorite?'active':''}">★</button></div>`}
const duplicateTooltipCache=new Map();
async function loadInlineDuplicatePaths(photo,tile){
 if(tile.dataset.dupePathsLoaded==='1')return;
 tile.dataset.dupePathsLoaded='1';
 const box=tile.querySelector('.duplicate-inline');if(!box)return;
 if(!photo.duplicate_count){box.innerHTML=`<div class="card-context-empty">${esc(t('cards.noDuplicates'))}</div>`;return}
 let items=duplicateTooltipCache.get(photo.id);
 if(!items){try{const d=await api(`/api/photos/${photo.id}/duplicates`);items=d.items||[];duplicateTooltipCache.set(photo.id,items)}catch{tile.dataset.dupePathsLoaded='';box.innerHTML=`<div class="card-context-empty">${esc(t('cards.duplicatesFailed'))}</div>`;return}}
 const dupes=(items||[]).filter(x=>Number(x.id)!==Number(photo.id)).slice(0,6);
 box.innerHTML=dupes.length?dupes.map(x=>`<button class="duplicate-copy" type="button" data-duplicate-id="${x.id}"><span><b>${esc((x.path||'').split(/[\\/]/).pop()||x.name||'')}</b><code>${esc(x.path||'')}</code><small>${esc(x.match_type||'duplicate')}${x.size?' · '+fmtBytes(x.size):''}</small></span></button>`).join(''):`<div class="card-context-empty">${esc(t('cards.noDuplicates'))}</div>`;
 box.querySelectorAll('[data-duplicate-id]').forEach(b=>b.onclick=e=>{e.stopPropagation();const x=(items||[]).find(v=>Number(v.id)===Number(b.dataset.duplicateId));if(x)openViewer(x,'duplicates')});
}
function refreshInlineDuplicatePaths(){if((document.body.dataset.view||'grid')!=='content')return;for(const tile of document.querySelectorAll('.tile[data-id]')){const r=tile.getBoundingClientRect();if(r.bottom>=-120&&r.top<=innerHeight+240){const p=currentItems.find(x=>Number(x.id)===Number(tile.dataset.id));if(p)loadInlineDuplicatePaths(p,tile)}}}
async function loadDuplicateTooltip(photo,tile){
 if(!photo.duplicate_count)return;
 let tip=tile.querySelector('.duplicate-path-tooltip');
 if(!tip){tip=document.createElement('div');tip.className='duplicate-path-tooltip';tile.appendChild(tip)}
 const render=items=>{const dupes=(items||[]).filter(x=>Number(x.id)!==Number(photo.id));const first=dupes.slice(0,2);const extra=Math.max(0,dupes.length-first.length);tip.innerHTML=`<div class="dup-tip-current">${esc(photo.path||'')}</div><div class="dup-tip-title">${esc(t('hover.duplicates'))}:</div>${first.map(x=>`<div class="dup-tip-path">${esc(x.path||'')}</div>`).join('')}${extra?`<div class="dup-tip-more">${esc(t('hover.more',{n:extra}))}</div>`:''}`;tip.classList.add('ready')};
 if(duplicateTooltipCache.has(photo.id)){render(duplicateTooltipCache.get(photo.id));return}
 tip.textContent=t('gallery.loading');
 try{const d=await api(`/api/photos/${photo.id}/duplicates`);duplicateTooltipCache.set(photo.id,d.items||[]);if(tile.matches(':hover'))render(d.items||[])}catch{tip.remove()}
}
function addTiles(items,opt={}){let min=0,max=0;if(opt.search&&items.length){const a=items.filter(x=>x.score!=null).map(x=>+x.score);if(a.length){min=Math.min(...a);max=Math.max(...a)}}for(const p of items){currentItems.push(p);if((document.body.dataset.view||'grid')==='timeline'){const g=(p.taken_at||'Unknown').slice(0,7);if(g!==lastTimelineGroup){lastTimelineGroup=g;const h=document.createElement('h3');h.className='timeline-head';h.textContent=g;grid.appendChild(h)}}const d=document.createElement('article');d.className='tile';d.dataset.id=p.id;d.tabIndex=0;if(p.duplicate_count)d.classList.add('has-duplicate');if(opt.search&&p.score!=null){d.classList.add('search-result');const good=(max-min)>1e-9?(+p.score-min)/(max-min):1;d.style.setProperty('--badness',(1-good).toFixed(3))}d.innerHTML=`<img loading="lazy" src="${p.thumbnail}" alt="${esc(p.name)}">${p.duplicate_count?`<button class="dupebadge" data-action="duplicates" aria-label="${esc(t('hint.duplicateBadge',{n:p.duplicate_count+1}))}">⧉ ${p.duplicate_count+1}</button>`:''}${tileActions(p)}<span class="pathhint" data-tooltip="${esc(p.path||'')}">${esc(p.path||'')}</span>${p.score!=null?`<span class="score" data-tooltip="${esc(t('hint.score'))}">${(+p.score).toFixed(3)}</span>`:''}${p.favorite?'<span class="favbadge">★</span>':''}<span class="meta">${esc(p.taken_at||'')}</span><div class="tile-details"><section class="content-main"><b class="content-name">${esc(p.name||'')}</b><code class="content-path">${esc(p.path||'')}</code><div class="content-facts"><span>${esc(p.taken_at||t('details.noDate'))}</span><span>${p.width&&p.height?`${p.width}×${p.height}`:'—'}</span><span>${fmtBytes(p.size||0)}</span>${p.rating?`<span>★ ${p.rating}</span>`:''}${p.favorite?'<span>★ '+esc(t('nav.favorites'))+'</span>':''}</div></section><section class="content-context"><header><b>${esc(t('cards.duplicates'))}</b><span>${p.duplicate_count?esc(t('cards.duplicateCount',{n:p.duplicate_count})):''}</span></header><div class="duplicate-inline"><div class="card-context-loading">${esc(t('gallery.loading'))}</div></div></section><div class="details-row"><b>${esc(p.name||'')}</b><strong>${esc(p.path||'')}</strong><span>${esc(p.taken_at||t('details.noDate'))}</span><span>${p.width&&p.height?`${p.width}×${p.height}`:'—'}</span><span>${fmtBytes(p.size||0)}</span><span>${p.duplicate_count?`⧉ ${p.duplicate_count+1}`:'—'}</span></div></div>`;
 d.addEventListener('click',ev=>handleTileClick(ev,p,d));d.addEventListener('dblclick',ev=>{ev.preventDefault();openViewer(p,'info')});d.addEventListener('contextmenu',ev=>{ev.preventDefault();showTileMenu(ev,p)});let lp=null;d.addEventListener('pointerdown',ev=>{if(ev.pointerType==='touch')lp=setTimeout(()=>showTileMenu(ev,p),520)});d.addEventListener('pointerup',()=>{clearTimeout(lp);lp=null});d.addEventListener('pointermove',()=>{if(lp){clearTimeout(lp);lp=null}});d.querySelectorAll('[data-action]').forEach(b=>b.onclick=ev=>{ev.stopPropagation();ev.currentTarget.blur();tileAction(b.dataset.action,p,d)});if(p.duplicate_count){for(const badge of [d.querySelector('.dupebadge'),d.querySelector('.duplicate-hover-action')].filter(Boolean)){badge.addEventListener('pointerenter',()=>loadDuplicateTooltip(p,d));badge.addEventListener('pointerleave',()=>d.querySelector('.duplicate-path-tooltip')?.classList.remove('ready'))}}bindBulge(d);grid.appendChild(d);if((document.body.dataset.view||'grid')==='content')requestAnimationFrame(()=>loadInlineDuplicatePaths(p,d))}}
function addParentFolderTile(){if(!folderId)return;const d=document.createElement('article');d.className='foldertile parent-folder';d.innerHTML=`<div class="foldericon">↰</div><div class="folderlabel">[..]</div><div class="foldercount">${esc(t('nav.up'))}</div>`;d.onclick=()=>{pushHistory();if(currentRel){const parts=currentRel.split(/[\\/]/).filter(Boolean);parts.pop();currentRel=parts.join('\\')}else{folderId=null;folderName='';currentRel=''}loadGallery(true);renderNav()};grid.appendChild(d)}
function addFolderTiles(items){for(const f of items){const d=document.createElement('article');d.className='foldertile';if(f.photo_count!=null)d.title=t('hint.folderCount',{n:f.photo_count});d.innerHTML=`<div class="foldericon">📁</div><div class="folderlabel">${esc(f.name)}</div><div class="foldercount" title="${esc(t('hint.folderRecursive',{direct:f.photo_count??0,total:f.recursive_photo_count??f.photo_count??0,folders:f.subfolder_count??0}))}">${esc(t('folder.counts',{photos:f.recursive_photo_count??f.photo_count??0,folders:f.subfolder_count??0}))}</div>`;d.onclick=()=>{pushHistory();currentRel=f.rel;loadGallery(true);renderNav()};grid.appendChild(d)}}
function handleTileClick(ev,p,tile){const idx=[...grid.querySelectorAll('.tile[data-id]')].indexOf(tile);if(ev.ctrlKey||ev.metaKey){selected.has(p.id)?selected.delete(p.id):selected.add(p.id);lastSelectedIndex=idx;updateSelectionBar();return}if(ev.shiftKey&&lastSelectedIndex>=0){const tiles=[...grid.querySelectorAll('.tile[data-id]')],a=Math.min(lastSelectedIndex,idx),b=Math.max(lastSelectedIndex,idx);for(let i=a;i<=b;i++)selected.add(Number(tiles[i].dataset.id));updateSelectionBar();return}openViewer(p,'info')}
async function tileAction(action,p,tile){if(action==='favorite'){const m=await api(`/api/photos/${p.id}/meta`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({favorite:!p.favorite})});p.favorite=!!m.favorite;const el=tile||grid.querySelector(`.tile[data-id=\"${p.id}\"]`);if(el){el.querySelector('[data-action=\"favorite\"]')?.classList.toggle('active',p.favorite);let badge=el.querySelector('.favbadge');if(p.favorite&&!badge){badge=document.createElement('span');badge.className='favbadge';badge.textContent='★';el.appendChild(badge)}else if(!p.favorite&&badge)badge.remove()}return}await openViewer(p,action==='duplicates'?'duplicates':action==='similar'?'similar':'info')}
function clearBulge(){for(const el of $$('.tile')){el.style.removeProperty('--bx');el.style.removeProperty('--by');el.classList.remove('bulged')}}
function bindBulge(tile){tile.addEventListener('mouseenter',()=>{if(!document.documentElement.classList.contains('motion')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=tile.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;for(const el of $$('.tile')){const q=el.getBoundingClientRect(),dx=q.left+q.width/2-cx,dy=q.top+q.height/2-cy,dist=Math.hypot(dx,dy);if(dist&&dist<360){const push=(1-dist/360)*7;el.style.setProperty('--bx',`${dx/dist*push}px`);el.style.setProperty('--by',`${dy/dist*push}px`);el.classList.add('bulged')}}tile.classList.add('hovered')});tile.addEventListener('mouseleave',()=>{tile.classList.remove('hovered');clearBulge()})}

async function loadGallery(reset=true,record=true){if(loadingPage)return;if(reset){searchMode=false;offset=0;grid.innerHTML='';currentItems=[];selected.clear();lastTimelineGroup=''}loadingPage=true;$('#loadHint').classList.remove('hidden');try{
 if(specialMode==='favorites'){const d=await api(`/api/photos?favorite=true&limit=${PAGE}&offset=${offset}&sort=${encodeURIComponent($('#sortSelect').value)}`);total=d.total;addTiles(d.items||[]);offset+=d.items.length;hasMore=offset<total;empty.classList.toggle('hidden',total>0);if(!total)empty.textContent=t('favorites.empty')}
 else if(specialMode==='duplicates'){const d=await api(`/api/duplicates?limit=${PAGE}&offset=${offset}&sort=${encodeURIComponent($('#sortSelect').value)}`);total=d.total;addTiles(d.items||[]);offset+=d.items.length;hasMore=offset<total;empty.classList.toggle('hidden',total>0);if(!total)empty.textContent=t('duplicates.empty')}
 else if(browseMode==='folders'&&!selectedTags.length&&folderId){const u=`/api/folder/browse?folder_id=${folderId}&rel=${encodeURIComponent(currentRel)}&limit=${PAGE}&offset=${offset}&sort=${encodeURIComponent($('#sortSelect').value)}`;const d=await api(u);total=d.total;if(reset){addParentFolderTile();addFolderTiles(d.subfolders||[]);}addTiles(d.items||[]);offset+=d.items.length;hasMore=offset<total;empty.classList.toggle('hidden',(d.subfolders.length+d.items.length)>0);if(!d.subfolders.length&&!d.items.length)empty.textContent=t('gallery.empty')}
 else if(browseMode==='folders'&&!selectedTags.length&&!folderId){const fs=await api('/api/folders');total=0;hasMore=false;$('#onboarding').classList.toggle('hidden',!!fs.length);for(const f of fs){const d=document.createElement('article');d.className='foldertile';d.title=t('hint.folderCount',{n:f.photo_count});d.innerHTML=`<div class="foldericon">📁</div><div class="folderlabel">${esc(f.path.split(/[\\/]/).filter(Boolean).pop()||f.path)}</div><div class="foldercount" title="${esc(f.path)}">${esc(t('folder.counts',{photos:f.photo_count||0,folders:f.subfolder_count||0}))}</div>`;d.onclick=()=>{pushHistory();folderId=f.id;folderName=f.path;currentRel='';loadGallery(true);renderNav()};grid.appendChild(d)}empty.classList.add('hidden')}
 else {const u=`/api/photos?limit=${PAGE}&offset=${offset}&sort=${encodeURIComponent($('#sortSelect').value)}${filterQuery()}`;const d=await api(u);total=d.total;addTiles(d.items||[]);offset+=d.items.length;hasMore=offset<total;empty.classList.toggle('hidden',total>0);if(!total)empty.textContent=t('gallery.empty')}
 updateCount();if(reset&&record)pushHistory();}catch(e){empty.textContent=e.message;empty.classList.remove('hidden')}finally{loadingPage=false;$('#loadHint').classList.add('hidden');requestAnimationFrame(refreshInlineDuplicatePaths)}}
async function runSearch(record=true){specialMode='';const q=$('#search').value.trim();if(!q){clearSearch(record);return}loadingPage=true;grid.innerHTML='';currentItems=[];selected.clear();lastTimelineGroup='';searchMode=true;try{const d=await api(`/api/search?q=${encodeURIComponent(q)}&limit=120&sort=${encodeURIComponent($('#sortSelect').value)}${filterQuery()}`);addTiles(d.items||[],{search:true});total=d.items.length;offset=total;hasMore=false;empty.classList.toggle('hidden',!!total);if(!total)empty.textContent=t('gallery.empty');updateCount();if(record)pushHistory()}catch(e){empty.textContent=e.message;empty.classList.remove('hidden')}finally{loadingPage=false}}
function clearSearch(record=true){$('#search').value='';searchMode=false;loadGallery(true,record)}
async function resetAll(){specialMode='';folderId=null;folderName='';currentRel='';selectedTags=[];$('#search').value='';searchMode=false;browseMode='folders';await renderNav();await loadGallery(true,true)}

async function renderNav(){$('#modeFolders').classList.toggle('active',browseMode==='folders'&&!specialMode);$('#modeTags').classList.toggle('active',browseMode==='tags'&&!specialMode);$('#modeFavorites').classList.toggle('active',specialMode==='favorites');$('#modeDuplicates').classList.toggle('active',specialMode==='duplicates');$('#navPanel').className='navpanel '+(browseMode==='tags'?'tags-mode':'folders-mode');$('#toggleNavPanel').classList.toggle('hidden',browseMode!=='tags');$('#navPanel').classList.toggle('collapsed',browseMode==='tags'&&tagsPanelCollapsed);$('#toggleNavPanel').textContent=tagsPanelCollapsed?'▾':'▴';
 if(browseMode==='tags'){const d=await api(`/api/tags?selected=${selectedTags.map(x=>x.id).join(',')}${folderId?'&folder_id='+folderId:''}${currentRel?'&rel='+encodeURIComponent(currentRel):''}`);$('#navPanel').innerHTML=d.items.map(x=>`<button class="navitem ${selectedTags.some(s=>s.id===x.id)?'active':''}" data-id="${x.id}" title="${esc(t('hint.tags'))}: ${x.count}">#${esc(x.name)} <span class="n">${x.count}</span></button>`).join('');$('#navPanel').querySelectorAll('.navitem').forEach(b=>b.onclick=()=>{const x=d.items.find(v=>v.id===+b.dataset.id),i=selectedTags.findIndex(v=>v.id===x.id);if(i>=0)selectedTags.splice(i,1);else selectedTags.push(x);loadGallery(true);renderNav()})}else $('#navPanel').innerHTML='';renderCrumbs()}
function renderCrumbs(){const c=$('#crumbs');c.innerHTML='';$('#newFolderBtn').classList.toggle('hidden',!folderId||!!specialMode);if(specialMode){const b=document.createElement('button');b.className='crumb';b.textContent=t(specialMode==='favorites'?'nav.favorites':'duplicates.title');c.appendChild(b);return}const home=document.createElement('button');home.className='crumb homecrumb';home.textContent=t('nav.photos');home.onclick=()=>resetAll();c.appendChild(home);if(!folderId)return;const sep=()=>{const x=document.createElement('span');x.className='crumbsep';x.textContent='›';c.appendChild(x)};sep();const root=document.createElement('button');root.className='crumb';root.textContent=folderName.split(/[\\/]/).filter(Boolean).pop()||folderName;root.onclick=()=>{pushHistory();currentRel='';loadGallery(true);renderNav()};c.appendChild(root);const parts=currentRel.split(/[\\/]/).filter(Boolean);const shownStart=Math.max(0,parts.length-3);let acc=[];for(let i=0;i<parts.length;i++){acc.push(parts[i]);if(parts.length>4&&i===0){sep();const dots=document.createElement('span');dots.className='crumbdots';dots.textContent='…';c.appendChild(dots)}if(i<shownStart)continue;sep();const rel=acc.join('\\'),b=document.createElement('button');b.className='crumb';b.textContent=parts[i];b.onclick=()=>{pushHistory();currentRel=rel;loadGallery(true);renderNav()};c.appendChild(b)}}

function setViewerTab(tab){viewerTab=tab;for(const [k,id] of Object.entries({info:'infoBtn',objects:'objectsBtn',similar:'similarBtn',duplicates:'duplicatesBtn'}))$('#'+id).classList.toggle('active',k===tab);loadViewerSide(tab)}
async function openViewer(p,tab='info'){clearBulge();document.activeElement?.blur?.();for(const b of $$('.tile-actions button'))b.blur();const ids=currentItems.map(x=>x.id).filter(Number.isFinite),ctx=specialMode==='duplicates'?'duplicates':'main',q=`tab=${encodeURIComponent(tab)}&ctx=${ctx}&ids=${encodeURIComponent(ids.join(','))}`;try{await api(`/api/window/viewer/${p.id}?${q}`,{method:'POST'})}catch(e){open(`/viewer?photo=${p.id}&${q}&v=2.2.15`,'_blank','popup,width=1500,height=950')}}
function closeViewer(){$('#viewer').classList.add('hidden');$('#viewerImg').removeAttribute('src');currentPhoto=null;viewerTab='info';clearBulge();document.activeElement?.blur?.()}
async function loadViewerSide(tab){if(!currentPhoto)return;const box=$('#viewerSideContent');box.innerHTML=`<div class="viewer-side-loading">${esc(t('gallery.loading'))}</div>`;try{
 if(tab==='info'){const d=await api(`/api/photos/${currentPhoto.id}/info`),e=d.exif||{},m=d.user_meta||{};const exp=[e.fnumber?`ƒ/${(+e.fnumber).toFixed(1)}`:'',e.exposure_time?`${e.exposure_time<1?'1/'+Math.round(1/e.exposure_time):e.exposure_time+'s'}`:'',e.iso?`ISO ${e.iso}`:'',e.focal_length?`${(+e.focal_length).toFixed(1)} mm`:''].filter(Boolean).join(' · ');box.innerHTML=`<div class="photo-info">${infoRow(t('info.date'),d.taken_at||e.datetime_original||'—')}${infoRow(t('info.dimensions'),d.width&&d.height?`${d.width} × ${d.height}`:'—')}${infoRow(t('info.size'),fmtBytes(d.size))}${infoRow(t('info.format'),d.suffix||'—')}${infoRow(t('info.camera'),[e.make,e.model].filter(Boolean).join(' ')||'—')}${infoRow(t('info.lens'),e.lens||'—')}${infoRow(t('info.exposure'),exp||'—')}${infoRow(t('info.gps'),e.latitude!=null?`${e.latitude.toFixed(6)}, ${e.longitude.toFixed(6)}${e.altitude!=null?' · '+Math.round(e.altitude)+' m':''}`:'—')}${infoRow(t('info.software'),e.software||'—')}<div class="info-block"><span>${t('info.path')}</span><code>${esc(d.path)}</code><div class="inline-actions"><button onclick="openFolder(${d.id})">📂</button><button onclick="openExternal(${d.id})">↗</button><button onclick="printPhoto(${d.id})">🖨</button></div></div><div class="info-block"><span>${t('info.tags')}</span><div class="tag-list">${(d.tags||[]).map(x=>`<span>#${esc(x.name)}</span>`).join('')}</div><div class="manual-tag"><input id="manualTagInput" placeholder="#tag"><button onclick="addManualTag(${d.id})">+</button></div></div><div class="rating-row"><button class="favorite-btn ${m.favorite?'active':''}" onclick="toggleViewerFavorite(${d.id},${m.favorite?0:1})">★</button><div class="stars">${[1,2,3,4,5].map(n=>`<button class="${m.rating>=n?'active':''}" onclick="setRating(${d.id},${n})">★</button>`).join('')}</div></div><label class="color-label-row"><span>${esc(t('info.color'))}</span><select id="photoColor" onchange="setColorLabel(${d.id},this.value)"><option value="">—</option><option value="red" ${m.color_label==='red'?'selected':''}>🔴</option><option value="yellow" ${m.color_label==='yellow'?'selected':''}>🟡</option><option value="green" ${m.color_label==='green'?'selected':''}>🟢</option><option value="blue" ${m.color_label==='blue'?'selected':''}>🔵</option><option value="purple" ${m.color_label==='purple'?'selected':''}>🟣</option></select></label><textarea id="photoComment" placeholder="${esc(t('info.comment'))}">${esc(m.comment||'')}</textarea><button class="save-comment" onclick="saveComment(${d.id})">${esc(t('settings.save'))}</button></div>`}
 else if(tab==='objects'){const d=await api(`/api/photos/${currentPhoto.id}/detections`);box.innerHTML=d.items.length?`<div class="detections">${d.items.map(x=>`<div class="detection"><img src="${x.crop}"><div><b>${esc(x.entity_name||x.kind_label)}</b><small>${Math.round(x.score*100)}%</small><div class="namebox"><input id="name-${x.id}" value="${esc(x.entity_name||'')}"><button onclick="nameDetection(${x.id})">✓</button></div></div></div>`).join('')}</div>`:`<div class="viewer-side-empty">—</div>`}
 else {const ep=tab==='similar'?'similar':'duplicates',d=await api(`/api/photos/${currentPhoto.id}/${ep}`);box.innerHTML=d.items.length?`<div class="viewer-results">${d.items.map(x=>`<button class="viewer-result" onclick='viewerResult(${JSON.stringify(x).replaceAll("'","&#39;")})'><img src="${x.thumbnail}"><span>${x.score!=null?(+x.score).toFixed(3):'⧉'}</span></button>`).join('')}</div>`:`<div class="viewer-side-empty">${esc(tab==='similar'?t('viewer.noSimilar'):t('viewer.noDuplicates'))}</div>`}
 }catch(e){box.innerHTML=`<div class="errorbox">${esc(e.message)}</div>`}}
function infoRow(k,v){return `<div class="photo-info-row"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`}
window.viewerResult=p=>openViewer(p,viewerTab);window.nameDetection=async id=>{const name=$(`#name-${id}`).value.trim();if(!name)return;await api(`/api/detections/${id}/name`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,propagate:true})});loadViewerSide('objects');renderNav()};window.openFolder=async id=>api(`/api/photos/${id}/open-folder`,{method:'POST'});window.openExternal=async id=>api(`/api/photos/${id}/open-external`,{method:'POST'});window.printPhoto=id=>{const w=open(`/api/photos/${id}/original`,'_blank');w?.addEventListener('load',()=>w.print())};window.addManualTag=async id=>{const name=$('#manualTagInput').value.trim();if(!name)return;await api('/api/tags/manual',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({photo_ids:[id],name})});loadViewerSide('info');renderNav()};window.toggleViewerFavorite=async(id,f)=>{await api(`/api/photos/${id}/meta`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({favorite:!!f})});loadViewerSide('info')};window.setRating=async(id,rating)=>{await api(`/api/photos/${id}/meta`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rating})});loadViewerSide('info')};window.setColorLabel=async(id,color_label)=>{await api(`/api/photos/${id}/meta`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({color_label})})};window.saveComment=async id=>{await api(`/api/photos/${id}/meta`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({comment:$('#photoComment').value})})};
function viewerStep(dir){if(!currentPhoto)return;const i=currentItems.findIndex(x=>x.id===currentPhoto.id),n=i+dir;if(n>=0&&n<currentItems.length)openViewer(currentItems[n],viewerTab)}

async function loadFolders(){const fs=await api('/api/folders'),box=$('#folderList');box.innerHTML='';for(const f of fs){const el=document.createElement('div');el.className='folder';el.innerHTML=`<div>${esc(f.path)} <span class="muted">(${f.photo_count})</span></div><button>${esc(t('settings.removeFolder'))}</button>`;el.querySelector('button').onclick=async()=>{if(confirm(t('confirm.removeFolder'))){await api('/api/folders/'+f.id,{method:'DELETE'});loadFolders();renderNav();loadGallery(true)}};box.appendChild(el)}}
function renderAI(i){const s=i.model_state||{};$('#modelState').textContent=s.loaded?(s.device==='cuda'?'GPU':s.backend==='remote'?'API':'CPU'):'';$('#aiInfo').innerHTML=`<div><b>${esc(s.model||'Auto')}</b></div><div>${esc(s.device_name||s.device||'')}</div><div>${i.photos||0} photos · ${i.embeddings||0} embeddings</div>`;const st=i.settings||{};$('#aiBackend').value=st.backend||'auto';$('#aiProfile').value=st.local_profile||'auto';$('#aiDevice').value=st.device||'auto';$('#remoteUrl').value=st.remote_base_url||'';$('#remoteModel').value=st.remote_model||'';$('#remoteKey').value=st.remote_api_key||'';$('#remoteSettings').classList.toggle('hidden',$('#aiBackend').value!=='remote')}
async function loadInfo(){const i=await api('/api/info');if(i.version&&i.version!==CLIENT_VERSION){const k='eidolarch.reloadForVersion';if(sessionStorage.getItem(k)!==i.version){sessionStorage.setItem(k,i.version);location.replace('/?v='+encodeURIComponent(i.version)+'&reload='+Date.now());return new Promise(()=>{})}}renderAI(i);try{const d=await api('/api/diagnostics?lines=20');const el=$('#diagInfo');if(el)el.textContent=[`Eidolarch ${d.version}`,`Python ${d.runtime.python||'?'}`,`Torch ${d.runtime.torch||'?'}`,`CUDA ${d.runtime.cuda_available?'yes':'no'}`,d.runtime.gpu||'',d.index_status.entity_last_error?`Objects: ${d.index_status.entity_last_error}`:''].filter(Boolean).join(' · ')}catch{}return i}
async function loadStorage(){const s=await api('/api/storage');$('#storageInfo').textContent=`DB ${fmtBytes(s.db_bytes)} · thumbnails ${fmtBytes(s.thumb_bytes)} · data ${fmtBytes(s.data_bytes)}`}

function showTileMenu(ev,p){
 const pop=$('#popover');pop.innerHTML=`<div class="context-menu"><button data-c="similar">≈ ${esc(t('tile.similar'))}</button><button data-c="duplicates">⧉ ${esc(t('tile.duplicates'))}</button><hr><button data-c="open">↗ ${esc(t('menu.openExternal'))}</button><button data-c="folder">📂 ${esc(t('menu.openFolder'))}</button><button data-c="print">🖨 ${esc(t('menu.print'))}</button><button data-c="rename">✎ ${esc(t('menu.rename'))}</button><hr><button data-c="copy">⧉ ${esc(t('menu.copy'))}</button><button data-c="cut">✂ ${esc(t('menu.cut'))}</button><button data-c="trash" class="danger-text">⌫ ${esc(t('menu.trash'))}</button></div>`;
 pop.classList.remove('hidden');pop.style.left=Math.min(ev.clientX,innerWidth-250)+'px';pop.style.top=Math.min(ev.clientY,innerHeight-360)+'px';pop.style.right='auto';
 pop.querySelectorAll('[data-c]').forEach(b=>b.onclick=async()=>{const a=b.dataset.c;hidePopover();if(a==='similar'||a==='duplicates')return tileAction(a,p);if(a==='open')return openExternal(p.id);if(a==='folder')return openFolder(p.id);if(a==='print')return printPhoto(p.id);if(a==='copy'||a==='cut'){clipboard={mode:a==='cut'?'move':'copy',ids:[p.id]};return}if(a==='rename'){const name=prompt(t('prompt.rename'),p.name);if(name){await api(`/api/files/rename/${p.id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({photo_ids:[p.id],new_name:name})});loadGallery(true,false)}return}if(a==='trash'){if(confirm(t('confirm.delete'))){await api('/api/files/trash',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({photo_ids:[p.id]})});showToast(`${esc(t('message.trashed'))} <button onclick="openRecycleBin()">${esc(t('message.openRecycleBin'))}</button>`);loadGallery(true,false)}}})
}

async function showNetwork(){const d=await api('/api/system/network'),p=$('#popover');p.innerHTML=`<h3>${esc(t('network.title'))}</h3>${d.addresses.length?d.addresses.map(a=>`<div class="network-row ${a.external?'external':''}"><code>${esc(a.url)}</code><button data-copy="${esc(a.url)}">${esc(t('network.copy'))}</button><a href="${esc(a.url)}" target="_blank">${esc(t('network.open'))}</a><img src="/api/system/network/qr?url=${encodeURIComponent(a.url)}"></div>`).join(''):`<p>${esc(t('network.no'))}</p>`}`;showPopover($('#networkBtn'));p.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>navigator.clipboard.writeText(b.dataset.copy))}
async function showJobs(){const d=await api('/api/jobs'),p=$('#popover');p.innerHTML=`<h3>${esc(t('jobs.title'))}</h3>${d.jobs.map(j=>`<div class="job-row"><span>${esc(t('job.'+j.id)||j.label)}</span><div class="mini-progress"><i style="width:${j.percent}%"></i></div><b>${j.percent}%</b></div>`).join('')}<button id="popPause">${esc(d.paused?t('jobs.resume'):t('jobs.pause'))}</button>`;showPopover($('#jobsBtn'));$('#popPause').onclick=async()=>{await api('/api/index/control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({paused:!d.paused})});showJobs()}}
function showPopover(anchor){const p=$('#popover'),r=anchor.getBoundingClientRect();p.classList.remove('hidden');p.style.top=`${r.bottom+8}px`;p.style.right=`${Math.max(8,innerWidth-r.right)}px`}
function hidePopover(){$('#popover').classList.add('hidden')}

async function showGraph(){try{await api('/api/window/graph',{method:'POST'})}catch{open('/graph?v=2.2.15','_blank','popup,width=1400,height=900')}}

async function bulkAction(op){const ids=[...selected];if(op==='cancel'){selected.clear();updateSelectionBar();return}if(op==='undo'){await api('/api/files/undo',{method:'POST'});loadGallery(true,false);return}if(op==='tag'){const name=prompt(t('prompt.tag'));if(name)await api('/api/tags/manual',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({photo_ids:ids,name})});return}if(op==='delete'){if(confirm(t('confirm.delete'))){await api('/api/files/trash',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({photo_ids:ids})});showToast(`${esc(t('message.trashed'))} <button onclick="openRecycleBin()">${esc(t('message.openRecycleBin'))}</button>`);selected.clear();loadGallery(true,false)}return}if(op==='copy'){clipboard={mode:'copy',ids};return}if(op==='move'){clipboard={mode:'move',ids};const dest=prompt(t('prompt.destination'),currentFolderPath());if(dest){await api('/api/files/move',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({photo_ids:ids,destination:dest})});selected.clear();loadGallery(true,false)}}}
function showToast(html,ms=6000){const el=$('#toast');clearTimeout(toastTimer);el.innerHTML=html;el.classList.remove('hidden');toastTimer=setTimeout(()=>el.classList.add('hidden'),ms)}
window.openRecycleBin=async()=>{try{await api('/api/system/recycle-bin',{method:'POST'})}catch(e){alert(e.message)}};
function currentFolderPath(){if(!folderName)return'';return currentRel?folderName.replace(/[\\/]$/,'')+'\\'+currentRel:folderName}
async function pasteClipboard(){if(!clipboard.ids.length)return;const dest=currentFolderPath()||prompt(t('prompt.destination'));if(!dest)return;await api(`/api/files/${clipboard.mode==='move'?'move':'copy'}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({photo_ids:clipboard.ids,destination:dest})});if(clipboard.mode==='move')clipboard={mode:null,ids:[]};loadGallery(true,false)}

function centerPhotoId(){const cy=innerHeight/2;let best=null,dist=Infinity;for(const el of document.querySelectorAll('.tile[data-id]')){const r=el.getBoundingClientRect(),d=Math.abs((r.top+r.bottom)/2-cy);if(d<dist){dist=d;best=el.dataset.id}}return best}function setView(v,reload=true){v=({large:'content',list:'details',timeline:'grid'}[v]||v);if(!['grid','content','details'].includes(v))v='grid';const keep=reload?centerPhotoId():null;document.body.dataset.view=v;localStorage.setItem('eidolarch.view',v);for(const b of document.querySelectorAll('.view-switch button'))b.classList.toggle('active',b.dataset.view===v);requestAnimationFrame(()=>{if(keep)grid.querySelector(`.tile[data-id="${keep}"]`)?.scrollIntoView({block:'center'});refreshInlineDuplicatePaths()})}
async function openHelp(topic='start'){try{await api(`/api/window/help?lang=${encodeURIComponent(lang)}`,{method:'POST'})}catch{open(`/help?lang=${encodeURIComponent(lang)}&v=2.2.15#${encodeURIComponent(topic)}`,'_blank','popup,width=1200,height=850')}}
function closeHelp(){$('#helpOverlay').classList.add('hidden');$('#helpFrame').src='about:blank'}

