async function chooseLibraryFolder(){try{const before=await api('/api/folders');const d=await api('/api/folders/pick',{method:'POST'});if(!d.path)return;await api('/api/folders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:d.path})});$('#folderPath').value='';await loadFolders();await renderNav();await loadGallery(true,false);if(!before.length&&confirm(t('onboarding.addAnother')))await chooseLibraryFolder()}catch(e){alert(e.message)}}
function showSettingsTab(name){$$('[data-settings-tab]').forEach(b=>b.classList.toggle('active',b.dataset.settingsTab===name));$$('[data-settings-panel]').forEach(p=>p.classList.toggle('hidden',p.dataset.settingsPanel!==name))}
